css:
.bk-satoko5 p{text-indent:1em;margin:0 0 2mm}
.bk-satoko5 .box p{text-indent:0}
.bk-satoko5 .sep{text-align:center;color:#888;margin:4mm 0;text-indent:0}
.bk-satoko5 .cast{display:flex;gap:1.5mm;margin:1mm 0 3mm}
.bk-satoko5 .cast div{flex:1;text-align:center;font-size:0.727em;color:#555}
.bk-satoko5 .cast svg{height:21mm;width:auto;max-width:100%;display:block;margin:0 auto 0.5mm}
.bk-satoko5 .fig{margin:3mm 0 4mm;text-align:center;}
.bk-satoko5 .fig svg{width:62%;height:auto;display:block;margin:0 auto}
.bk-satoko5 .fig .cap{font-size:0.818em;color:#555;margin-top:1.5mm;text-indent:0}
.bk-satoko5 .cb{text-align:center;padding-top:4mm}
.bk-satoko5 .cbh{display:inline-block;background:#7a5230;color:#fff;border-radius:99px;padding:1.2mm 5mm;font-size:0.955em;margin-bottom:4mm}
.bk-satoko5 .cb .pic svg{width:100%;height:auto;border-radius:3mm;display:block}
.bk-satoko5 .cb .dogs{display:flex;gap:2mm}
.bk-satoko5 .cb .dogs>div{flex:1;min-width:0}
.bk-satoko5 .cb .dogs svg{width:100%;height:auto;display:block;border-radius:3mm}
.bk-satoko5 .cbt{text-align:left;font-size:0.955em;line-height:1.75;margin-top:4mm;background:#fbf6ee;border:1px solid #eadfcd;border-radius:3mm;padding:3mm 3.5mm}
.bk-satoko5 .cbt p{text-indent:0;margin:0}
.bk-satoko5 .cbt b{font-size:1.05em;color:#7a5230}
.bk-satoko5 .cth{font-size:1.27em;color:#fff;background:var(--c);padding:1.5mm 3mm;margin:0 0 3mm;border-radius:3px}
.bk-satoko5 .ctab{width:100%;border-collapse:collapse}
.bk-satoko5 .ctab td{border-bottom:1px dotted #ccc;padding:1mm;font-size:0.909em;vertical-align:top}
